function model(p) {
  // Member records from up to five source systems flow through a customer data platform in one month:
  // a quality check rejects bad records, identity resolution merges duplicates into existing profiles,
  // and consent decides whether a profile update can be activated for marketing as well as service.
  // Volumes and rates are illustrative, not measured.
  const n = Math.max(2, Math.min(5, Math.round(p.sources)));
  const dup = Math.max(0, Math.min(0.6, Math.round(p.duplicateRate) / 100));
  const consent = Math.max(0.2, Math.min(1, Math.round(p.consentRate) / 100));
  const filter = Math.round(p.qualityFilter) === 1;
  const SOURCES = [
    { id: 'portal', label: 'Member portal', vol: 4200, reject: 0.06, icon: 'globe' },
    { id: 'claims', label: 'Claims system', vol: 6500, reject: 0.03, icon: 'file-text' },
    { id: 'contact', label: 'Contact centre', vol: 3100, reject: 0.12, icon: 'headset' },
    { id: 'marketing', label: 'Marketing platform', vol: 2800, reject: 0.18, icon: 'mail' },
    { id: 'pharmacy', label: 'Pharmacy', vol: 1900, reject: 0.08, icon: 'pill' }
  ].slice(0, n);
  // Stage 1: quality check per source (invalid member number, missing date of birth, test records)
  const links = [], nodes = [];
  const node = (id, label, col, kind) => { nodes.push({ id, label, col, kind, value: 0 }); };
  SOURCES.forEach(s => node(s.id, s.label, 0, 'source'));
  node('passed', 'Passed quality check', 1, 'stage');
  node('rejected', 'Rejected', 1, 'sink');
  node('new', 'New profiles', 2, 'stage');
  node('merged', 'Merged into existing profiles', 2, 'stage');
  node('mkt', 'Marketing + service', 3, 'sink');
  node('svc', 'Service only', 3, 'sink');
  const link = (source, target, value, kind) => { if (value > 0) links.push({ source, target, value, kind }); };
  let passed = 0, rejected = 0;
  SOURCES.forEach(s => {
    const rej = filter ? Math.round(s.vol * s.reject) : 0, ok = s.vol - rej;
    s.rejected = rej; s.passed = ok;
    link(s.id, 'passed', ok, 'ok');
    link(s.id, 'rejected', rej, 'bad');
    passed += ok; rejected += rej;
  });
  // Stage 2: identity resolution. A share of the passed records matches an existing profile and merges into it.
  const merged = Math.round(passed * dup), fresh = passed - merged;
  link('passed', 'new', fresh, 'ok');
  link('passed', 'merged', merged, 'merge');
  // Stage 3: consent. Every profile update reaches service; only consented ones may also activate marketing.
  const newMkt = Math.round(fresh * consent), newSvc = fresh - newMkt;
  const mergedMkt = Math.round(merged * consent), mergedSvc = merged - mergedMkt;
  link('new', 'mkt', newMkt, 'consent');
  link('new', 'svc', newSvc, 'ok');
  link('merged', 'mkt', mergedMkt, 'consent');
  link('merged', 'svc', mergedSvc, 'ok');
  const ingested = SOURCES.reduce((a, s) => a + s.vol, 0);
  const marketing = newMkt + mergedMkt, service = newSvc + mergedSvc;
  // Node values: sources carry their volume; the others the flow into them
  nodes.forEach(nd => { nd.value = nd.kind === 'source' ? SOURCES.find(s => s.id === nd.id).vol : links.filter(l => l.target === nd.id).reduce((a, l) => a + l.value, 0); });
  // A node with no flow (Rejected with the filter off, Merged at 0 % duplicates) is marked rather than drawn
  const used = new Set(links.flatMap(l => [l.source, l.target]));
  nodes.forEach(nd => { nd.active = used.has(nd.id); });
  const inactive = nodes.filter(nd => !nd.active).map(nd => nd.label).join(', ') || 'none';
  const pct = (a, b) => (b ? Math.round(100 * a / b) : 0);
  const fmt = v => v.toLocaleString('en-US');
  const steps = [
    { id: 'arrive', t: 0, title: 'Records arrive', note: fmt(ingested) + ' records a month from ' + n + ' source' + (n > 1 ? 's' : '') + '. A box-and-arrow diagram shows the same five arrows for all of them; the widths show who really feeds the platform.', col: 0 },
    { id: 'quality', t: 4.5, title: 'Quality check', note: filter
      ? fmt(rejected) + ' records (' + pct(rejected, ingested) + ' %) fail the quality check: invalid member numbers, missing dates of birth, test records. They never reach a profile.'
      : 'The quality filter is off. Every record passes, including the ones with invalid member numbers, and they will all land in profiles.', col: 1 },
    { id: 'identity', t: 9, title: 'Identity resolution', note: fmt(merged) + ' records (' + pct(merged, passed) + ' %) match a profile the platform already has and merge into it; ' + fmt(fresh) + ' create new profiles. Merging is not losing: those records still update a member.', col: 2 },
    { id: 'consent', t: 13.5, title: 'Consent decides activation', note: 'Every profile update reaches the service agent. ' + fmt(marketing) + ' (' + pct(marketing, passed) + ' %) carry marketing consent and can also start a journey; ' + fmt(service) + ' are service only.', col: 3 },
    { id: 'sowhat', t: 18, title: 'So what for architects', note: 'Of ' + fmt(ingested) + ' records, ' + fmt(marketing) + ' can be marketed to. The width of a flow, not the presence of an arrow, is what a capacity, licence or consent conversation should start from.', col: 3 }
  ];
  const summary = fmt(ingested) + ' records in: ' + fmt(rejected) + ' rejected, ' + fmt(merged) + ' merged, ' + fmt(fresh) + ' new profiles; ' + fmt(marketing) + ' can be marketed to, ' + fmt(service) + ' service only.';
  return {
    sources: SOURCES, nodes, links, inactive, filter, dup, consent,
    totals: { ingested, rejected, passed, merged, fresh, marketing, service },
    steps, duration: 21, markers: steps.map(s => s.t), summary
  };
}

checkCode:
function check(p) {
  const m = model(p), T = m.totals;
  // Conservation: what flows into every middle node flows out of it, and every record ends in exactly one outcome
  const inflow = id => m.links.filter(l => l.target === id).reduce((a, l) => a + l.value, 0);
  const outflow = id => m.links.filter(l => l.source === id).reduce((a, l) => a + l.value, 0);
  const middle = m.nodes.filter(n => n.kind === 'stage');
  const conserved = middle.every(n => inflow(n.id) === outflow(n.id));
  const sourcesOut = m.sources.every(s => outflow(s.id) === s.vol);
  const ends = T.rejected + T.marketing + T.service === T.ingested;
  // The controls do what they say: no rejections with the filter off, merge and consent shares within rounding of the sliders
  const filterOk = m.filter ? T.rejected > 0 : T.rejected === 0;
  const mergeOk = Math.abs(T.merged - T.passed * m.dup) <= 1;
  const consentOk = Math.abs(T.marketing - T.passed * m.consent) <= 2;
  const positive = m.links.every(l => l.value > 0);
  const pass = conserved && sourcesOut && ends && filterOk && mergeOk && consentOk && positive;
  return {
    pass,
    detail: T.ingested.toLocaleString('en-US') + ' records: ' + T.rejected.toLocaleString('en-US') + ' rejected + ' + T.marketing.toLocaleString('en-US') + ' marketing + ' + T.service.toLocaleString('en-US') + ' service only' +
      (ends ? ' add up' : ' do not add up') + '; every stage passes on what it receives' + (conserved ? '' : ' (violated)') + '; merged share ' + Math.round(100 * T.merged / T.passed) + ' %, consented share ' + Math.round(100 * T.marketing / T.passed) + ' %.'
  };
}
